<?php
declare(strict_types=1);
function ensureAccountRequestSchema(mysqli $conn): void {
 static $done=false;if($done)return;
 $conn->query("CREATE TABLE IF NOT EXISTS account_requests (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,employee_id VARCHAR(50) NOT NULL,full_name VARCHAR(255) NOT NULL,email VARCHAR(191) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('hr','employee') NOT NULL,department_id INT NULL,requested_by INT NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',decided_by INT NULL,decided_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_request_employee_id(employee_id),UNIQUE KEY unique_pending_email(email,status),KEY request_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");$done=true;
}
function submitAccountRequest(mysqli $conn,int $hrId,array $input): void {
 ensureAccountRequestSchema($conn);$name=trim((string)($input['full_name']??''));$email=trim((string)($input['email']??''));$password=(string)($input['password']??'');$role=(string)($input['role']??'');$department=filter_var($input['department_id']??'',FILTER_VALIDATE_INT);$department=$department?:null;
 if($name===''||mb_strlen($name)>255||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>191||strlen($password)<8||!in_array($role,['employee','hr'],true))throw new InvalidArgumentException('Enter a valid name, email, password of at least 8 characters, and employee role.');
 $exists=$conn->prepare('SELECT id FROM users WHERE email=? UNION SELECT id FROM account_requests WHERE email=? AND status="pending"');$exists->bind_param('ss',$email,$email);$exists->execute();if($exists->get_result()->num_rows)throw new InvalidArgumentException('An account or pending request already uses this email.');
 $max=(int)$conn->query("SELECT COALESCE(MAX(employee_number),0)+1 FROM (SELECT CAST(SUBSTRING(employee_id,5) AS UNSIGNED) employee_number FROM users WHERE employee_id LIKE 'EMP-%' UNION ALL SELECT CAST(SUBSTRING(employee_id,5) AS UNSIGNED) FROM account_requests WHERE employee_id LIKE 'EMP-%') ids")->fetch_row()[0];$emp='EMP-'.str_pad((string)$max,5,'0',STR_PAD_LEFT);$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conn->prepare("INSERT INTO account_requests(employee_id,full_name,email,password_hash,role,department_id,requested_by) VALUES(?,?,?,?,?,?,?)");$stmt->bind_param('sssssii',$emp,$name,$email,$hash,$role,$department,$hrId);$stmt->execute();
}
function decideAccountRequest(mysqli $conn,int $adminId,int $requestId,string $decision): void {
 ensureAccountRequestSchema($conn);if(!in_array($decision,['approved','rejected'],true))throw new InvalidArgumentException('Choose approve or reject.');$conn->begin_transaction();try{$q=$conn->prepare("SELECT * FROM account_requests WHERE id=? AND status='pending' FOR UPDATE");$q->bind_param('i',$requestId);$q->execute();$row=$q->get_result()->fetch_assoc();if(!$row)throw new InvalidArgumentException('This request was already handled.');if($decision==='approved'){$user=$conn->prepare("INSERT INTO users(employee_id,full_name,email,password,role,department_id,work_shift,status) VALUES(?,?,?,?,?,?,'morning','active')");$user->bind_param('sssssi',$row['employee_id'],$row['full_name'],$row['email'],$row['password_hash'],$row['role'],$row['department_id']);$user->execute();}$u=$conn->prepare('UPDATE account_requests SET status=?,decided_by=?,decided_at=NOW() WHERE id=?');$u->bind_param('sii',$decision,$adminId,$requestId);$u->execute();$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}
}
